import{_ as t,o,c as a,a3 as i}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Hermeticity","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Hermeticity | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/hermeticity"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/hermeticity"}]]},"headers":[],"relativePath":"xclang/design/hermeticity.md","filePath":"en/xclang/design/hermeticity.md","lastUpdated":1791227177000}'),r={name:"xclang/design/hermeticity.md"};function s(n,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="hermeticity" tabindex="-1">Hermeticity <a class="header-anchor" href="#hermeticity" aria-label="Permalink to &quot;Hermeticity&quot;">​</a></h1><p>xclang holds every target to one rule:</p><blockquote><p>A program depends at run time only on the system libraries every installation of its OS has and no one may redistribute. Everything else is linked into it. At build time, the only inputs from outside the toolchain are vendor SDKs, pinned.</p></blockquote><p>This page says what the rule gives, what it costs, and the places where it had to bend.</p><h2 id="what-a-program-loads" tabindex="-1">What a program loads <a class="header-anchor" href="#what-a-program-loads" aria-label="Permalink to &quot;What a program loads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>at run time, from the system</th><th>linked statically</th></tr></thead><tbody><tr><td>Linux (glibc)</td><td>glibc 2.17 or later: <code>libc</code>, <code>libm</code>, <code>libpthread</code>, <code>libdl</code>, <code>librt</code>, the dynamic loader</td><td>libc++, libc++abi, libunwind, the builtins</td></tr><tr><td>macOS</td><td>libSystem (the C library and the unwinder), the system frameworks the program links</td><td>libc++, libc++abi, the builtins</td></tr><tr><td>Windows (MinGW)</td><td>the OS&#39;s DLLs (<code>kernel32</code>, ...), UCRT (<code>api-ms-win-crt-*</code>, part of Windows 10 and later)</td><td>libc++, libc++abi, libunwind, the builtins, winpthreads, mingw-w64&#39;s own runtime</td></tr></tbody></table><p>The system libraries in the left column are the ones no one can ship with a program: glibc&#39;s dynamic loader and libc are one ABI with the kernel interface of the machine, libSystem is the only supported way into the macOS kernel, and UCRT is a component of Windows. Everything in the right column could be a shared library the program carries or a package the user installs; xclang makes it part of the program instead, so a program is one file that runs where it is copied.</p><p>The toolchain follows the rule too: clang and lld are linked statically against xclang&#39;s own libc++ on every host, macOS included. The system&#39;s <code>libc++.dylib</code> is never used, and <code>tests/smoke.ts</code> checks on every host that the toolchain&#39;s own programs load no C++ runtime and need glibc 2.17 at most.</p><h2 id="why-not-shared-runtimes" tabindex="-1">Why not shared runtimes <a class="header-anchor" href="#why-not-shared-runtimes" aria-label="Permalink to &quot;Why not shared runtimes&quot;">​</a></h2><p>A shared libc++ is what most toolchains do, and it has a cost the user pays later:</p><ul><li><strong>The program needs it at run time.</strong> On Linux, <code>libc++.so.1</code> is not on a default installation; a program linked against it needs a package, an rpath and a copy beside it, or a container. On Windows, <code>libc++.dll</code> must be shipped next to every program. On macOS, the system&#39;s <code>libc++.dylib</code> is the OS&#39;s version of libc++, not the headers&#39; the program was compiled with.</li><li><strong>Its version is the machine&#39;s.</strong> A shared library loaded from the system is the one the system has, which is not the one the program was built and tested with.</li><li><strong>The build&#39;s environment leaks into the program.</strong> conda-forge&#39;s compilers, for example, link against <code>libcxx</code> and <code>libstdcxx</code> packages and add them to the package&#39;s run-time dependencies through <code>run_exports</code>: right inside conda, where the environment provides them, and a dependency outside it.</li></ul><p>The price of static runtimes is size (every program carries the parts of libc++ it uses) and the one-runtime-per-shared-object rule below. For programs and tools that are copied to machines, xclang takes that price.</p><h2 id="one-libc-per-shared-object" tabindex="-1">One libc++ per shared object <a class="header-anchor" href="#one-libc-per-shared-object" aria-label="Permalink to &quot;One libc++ per shared object&quot;">​</a></h2><p>libc++, libc++abi and libunwind are built as static libraries with hidden symbols (<code>LIBCXX_HERMETIC_STATIC_LIBRARY</code>, <code>LIBCXXABI_HERMETIC_STATIC_LIBRARY</code>, <code>LIBUNWIND_HIDE_SYMBOLS</code>), and position-independent, so a shared library can carry them too. Every program and every shared library linked by xclang has a private copy. That has consequences, and they are the same ones the Android NDK documents for its static libc++ (&quot;you can only use a static variant of the C++ runtime if you have one and only one shared library in your application&quot;, <a href="https://developer.android.com/ndk/guides/cpp-support" target="_blank" rel="noreferrer">C++ library support</a>):</p><ul><li><strong>C++ objects should not cross shared objects.</strong> A <code>std::string</code> made by one copy of libc++ and destroyed by another mixes the state of two runtimes; memory one shared library allocates should be freed by the same library.</li><li><strong>Exceptions and RTTI across shared objects.</strong> Each copy has its own <code>type_info</code> for <code>std::exception</code> and the rest. On Linux and macOS libc++ compares type information by address, so a standard exception thrown in one shared library is caught in another only by <code>catch (...)</code>, not by <code>catch (const std::exception&amp;)</code>. Windows compares it by name, and catches it. (libc++ can compare by name everywhere, at the cost of a string comparison on every mismatch and of treating same-named types in anonymous namespaces as one; xclang keeps the default.)</li><li><strong>Globals are per copy</strong>: <code>std::cout</code>&#39;s buffer, the locale, the <code>new_handler</code>.</li></ul><p>A program whose libraries are linked into it, the default xclang is built for, has none of these problems. A plugin interface across shared objects should be a C interface, which is good practice regardless of the toolchain.</p><p>This is also why the Bazel module turns <code>supports_dynamic_linker</code> off. Bazel links <code>cc_test</code> and <code>cc_library</code> dependencies dynamically by default, one shared object per library, and kotatsu&#39;s tests built that way crashed at start-up with a double free, every shared object with a libc++ of its own. On Windows the default DLL of a <code>cc_library</code> did not link at all. Libraries now link statically into tests and programs; <code>cc_binary(linkshared = True)</code> still makes a shared library, and <code>features = [&quot;supports_dynamic_linker&quot;]</code> gives a target Bazel&#39;s dynamic linking back (<a href="./../integrations/bazel#what-the-toolchain-does">Bazel</a>).</p><h2 id="why-glibc-2-17" tabindex="-1">Why glibc 2.17 <a class="header-anchor" href="#why-glibc-2-17" aria-label="Permalink to &quot;Why glibc 2.17&quot;">​</a></h2><p>A program linked against a glibc runs on that version and every later one, never an earlier one: glibc versions its symbols, and the linker picks the newest version of each symbol the build&#39;s glibc has. So the glibc a Linux program is linked against is its floor, and building on a current distribution gives a program that needs a current distribution.</p><p>xclang&#39;s Linux sysroots hold glibc 2.17&#39;s headers, startup files and libraries, taken from conda-forge&#39;s <code>sysroot_linux-64</code> and <code>sysroot_linux-aarch64</code> 2.17 packages. 2.17 is the floor conda-forge and Rust&#39;s official Linux targets also use (<a href="https://github.com/rust-lang/rust/blob/main/src/ci/docker/host-x86_64/dist-x86_64-linux/Dockerfile" target="_blank" rel="noreferrer">Rust&#39;s dist builder</a> builds on CentOS 7 for it), so a program from xclang runs on CentOS 7, Debian 8, Ubuntu 14.04 and anything later.</p><p>The floor has costs, in <a href="./../reference/compatibility">compatibility</a>: no <code>-static-pie</code> (glibc 2.17 has no <code>rcrt1.o</code>), <code>-pg</code> needs <code>-no-pie</code>, no <code>quadmath.h</code>. <code>__cxa_thread_atexit_impl</code> arrived in glibc 2.18, so libc++abi is built with its own fallback for <code>thread_local</code> destructors. A newer glibc for programs that need what 2.17 lacks is <a href="./roadmap#targets">being considered</a> as a target of its own.</p><p>Two things about the sysroots took work:</p><ul><li><strong><code>-static</code> links.</strong> glibc 2.17&#39;s <code>libpthread.a</code> is one object that redefines <code>libc.a</code>&#39;s <code>__libc_sigaction</code> and cancellation points, and libunwind&#39;s dependency note pulls it in after <code>libc.a</code>: every <code>-static</code> link failed with duplicate symbols. The sysroot&#39;s <code>libc.a</code> is a linker script, <code>GROUP(libpthread.a libglibc.a)</code>, so both come in together and in an order that links.</li><li><strong>No symlinks.</strong> A Linux sysroot is full of links (<code>lib -&gt; lib64</code>, <code>libm.so -&gt; libm.so.6</code>), which Windows creates only with extra rights and conda packages for Windows cannot carry. Soname links are the files themselves, and <code>libfoo.so</code> development links are linker scripts (<code>INPUT(libfoo.so.6)</code>), as glibc&#39;s own <code>libc.so</code> is. Eight netfilter headers that differ from another only by case are left out, so a sysroot unpacks on a case-insensitive file system.</li></ul><h2 id="gcc-library-names" tabindex="-1">GCC library names <a class="header-anchor" href="#gcc-library-names" aria-label="Permalink to &quot;GCC library names&quot;">​</a></h2><p>Build scripts written for GCC name GCC&#39;s runtime libraries: <code>-latomic</code> for wide atomics, <code>-lgcc_s</code> and <code>-lgcc_eh</code> for the unwinder, <code>-lgcc</code> for the builtins, <code>-lssp</code> for the stack protector on MinGW. Rust&#39;s standard library names <code>-lgcc_s</code> when its linker is a C compiler. Their functions are in compiler-rt, libunwind and mingw-w64 here, so each name is an empty archive: the link finds the library it asked for, and the symbols come from where they are.</p><ul><li><code>-latomic</code>: the <code>__atomic_*</code> functions of atomics too wide to be lock-free (a struct, <code>__int128</code> without cx16) are in compiler-rt&#39;s builtins, built with <code>COMPILER_RT_EXCLUDE_ATOMIC_BUILTIN=OFF</code>.</li><li><code>-lssp</code>, <code>-lssp_nonshared</code>: clang&#39;s MinGW driver adds them for <code>-fstack-protector</code>; the functions are in mingw-w64&#39;s <code>libmingwex</code>.</li><li><code>-lstdc++</code> needs no stub: clang&#39;s driver replaces it with the C++ library it links, libc++ (unless <code>-nostdlib</code>, <code>-nodefaultlibs</code> or <code>-nostdlib++</code>).</li><li><code>windres</code>, the name CMake looks for to compile a MinGW project&#39;s <code>.rc</code> files, is <code>llvm-windres</code>.</li></ul><p>So a C++ program, a CMake project or a Rust crate written for GCC links unchanged. One limit: an empty <code>libgcc_s.a</code> gives Rust&#39;s standard library no unwinder, which links with <code>-nodefaultlibs</code>; Rust builds name libunwind themselves (<a href="./../integrations/cargo">Rust and cargo</a>).</p><h2 id="the-exceptions" tabindex="-1">The exceptions <a class="header-anchor" href="#the-exceptions" aria-label="Permalink to &quot;The exceptions&quot;">​</a></h2><ul><li><strong>Sanitizer runtimes.</strong> On macOS they are dylibs, which a program loads from the toolchain or from its own directory; an ASan build is for testing, not for shipping.</li><li><strong>macOS&#39;s SDK.</strong> Apple&#39;s SDK cannot be redistributed, so macOS targets build against Xcode&#39;s, found by <code>xcrun</code>: the one input from outside the toolchain. Fetching it from Apple, by version and digest, is <a href="./vendor-sdks">in research</a>.</li><li><strong>The bar for the future targets</strong> is the same: musl targets would be fully static; MSVC targets link the VC runtime and the STL statically and UCRT dynamically, Microsoft&#39;s &quot;hybrid CRT&quot; (<a href="./roadmap#targets">roadmap</a>).</li></ul><h2 id="checked-by" tabindex="-1">Checked by <a class="header-anchor" href="#checked-by" aria-label="Permalink to &quot;Checked by&quot;">​</a></h2><ul><li>tests/smoke.ts, on every host: the toolchain&#39;s own programs load no C++ runtime and need glibc 2.17 at most; programs build for every target and run where the machine can run them; <code>-static</code>, <code>-latomic</code>, the GCC names and <code>windres</code> work.</li><li><a href="https://github.com/clice-io/xclang/blob/main/.github/workflows/examples.yml" target="_blank" rel="noreferrer">examples.yml</a>, on every host: <code>llvm-readobj --needed-libs</code> of the quick start&#39;s programs for every target, the libraries listed above and nothing else.</li></ul>',31)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
